CREATE TABLE orders(id BINARY(16) NOT NULL PRIMARY KEY,user_id BINARY(16) NOT NULL,tenant_id BINARY(16) NOT NULL,event_id BINARY(16) NOT NULL,reservation_id BINARY(16) NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,payment_proof_reference VARCHAR(255),CONSTRAINT uk_order_reservation UNIQUE(reservation_id));
CREATE TABLE order_outbox(id BINARY(16) NOT NULL PRIMARY KEY,order_id BINARY(16) NOT NULL,event_type VARCHAR(64) NOT NULL,payload LONGTEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,processed BOOLEAN NOT NULL DEFAULT FALSE,INDEX ix_order_outbox_pending(processed,created_at));
